def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        order = OrderedDict()
        lock = threading.RLock()
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for k, v in sorted(kwargs.items()))
            with lock:
                if key in cache:
                    order.move_to_end(key)
                    return cache[key]
                result = func(*args, **kwargs)
                cache[key] = result
                order[key] = None
                if len(order) > maxsize:
                    oldest = next(iter(order))
                    del order[oldest]
                    del cache[oldest]
                return result
        wrapper.cache_info = lambda: (len(cache), maxsize, len(order))
        wrapper.cache_clear = lambda: (cache.clear(), order.clear())
        return wrapper
    return decorator
```

